class Solution {
public:
    int numDifferentIntegers(string word) {
        for (char& c : word)
            if (!isdigit((unsigned char)c)) c = ' ';
        istringstream in(word);
        string tok;
        unordered_set<string> seen;
        while (in >> tok) {
            size_t s = tok.find_first_not_of('0');
            seen.insert(s == string::npos ? "0" : tok.substr(s));
        }
        return seen.size();
    }
};

