class Solution {
    public int numDifferentIntegers(String word) {
        Set<String> seen = new HashSet<>();
        for (String tok : word.replaceAll("[^0-9]", " ").split(" ")) {
            if (tok.isEmpty()) continue;
            int s = 0;
            while (s < tok.length() - 1 && tok.charAt(s) == '0') s++;
            seen.add(tok.substring(s));
        }
        return seen.size();
    }
}

