class Solution:
    def numDifferentIntegers(self, word: str) -> int:
        seen = set()
        i, n = 0, len(word)
        while i < n:
            if not word[i].isdigit():
                i += 1
                continue
            j = i
            while j < n and word[j].isdigit():
                j += 1
            k = i
            while k < j - 1 and word[k] == '0':
                k += 1
            seen.add(word[k:j])
            i = j
        return len(seen)

