class Solution {
public:
    int numDifferentIntegers(string word) {
        unordered_set<string> seen;
        int n = word.size(), i = 0;
        while (i < n) {
            if (!isdigit((unsigned char)word[i])) { ++i; continue; }
            int j = i;
            while (j < n && isdigit((unsigned char)word[j])) ++j;
            int k = i;
            while (k < j - 1 && word[k] == '0') ++k;
            seen.insert(word.substr(k, j - k));
            i = j;
        }
        return seen.size();
    }
};

