var numDifferentIntegers = function(word) {
    const isDigit = (c) => c >= '0' && c <= '9';
    const seen = new Set();
    let i = 0;
    const n = word.length;
    while (i < n) {
        if (!isDigit(word[i])) { i++; continue; }
        let j = i;
        while (j < n && isDigit(word[j])) j++;
        let k = i;
        while (k < j - 1 && word[k] === '0') k++;
        seen.add(word.slice(k, j));
        i = j;
    }
    return seen.size;
};
